@RequiresApi(30) private static void setSurfaceFrameRateV30(Surface surface,float frameRate){
  int compatibility=frameRate == 0 ? Surface.FRAME_RATE_COMPATIBILITY_DEFAULT : Surface.FRAME_RATE_COMPATIBILITY_FIXED_SOURCE;
  try {
    surface.setFrameRate(frameRate,compatibility);
  } catch (IllegalArgumentException | IllegalStateException e) {
    e.printStackTrace();
  }
}
